export const API_URL = "http://localhost:12717/api/auth";

// --- Работа с токенами ---
export const getAccessToken = () => localStorage.getItem("accessToken");
export const getRefreshToken = () => localStorage.getItem("refreshToken");

// --- Декодирование JWT ---
export const decodeJWT = (token) => {
    try {
        const base64Url = token.split('.')[1];
        if (!base64Url) return null;

        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const padded = base64.padEnd(base64.length + (4 - base64.length % 4) % 4, '=');

        return JSON.parse(atob(padded));
    } catch (error) {
        console.error("Error decoding JWT:", error);
        return null;
    }
};

// --- Сохранение токенов ---
export const saveTokens = (access, refresh) => {
    localStorage.setItem("accessToken", access);
    localStorage.setItem("refreshToken", refresh);

    const decoded = decodeJWT(access);
    if (decoded) {
        localStorage.setItem("userId", decoded.id);
        localStorage.setItem("userRoles", JSON.stringify(decoded.roles || []));
        localStorage.setItem("userEmail", decoded.sub);
    }
};

// --- Получение текущего пользователя из JWT ---
export const getCurrentUser = () => {
    const token = getAccessToken();
    if (!token) return null;

    const decoded = decodeJWT(token);
    if (!decoded) return null;

    return {
        id: decoded.id || null,
        email: decoded.sub || "",
        roles: decoded.roles || [],
    };
};

// --- Логаут ---
export const logout = () => {
    localStorage.removeItem("accessToken");
    localStorage.removeItem("refreshToken");
    localStorage.removeItem("userRoles");
    localStorage.removeItem("userEmail");
    localStorage.removeItem("userId");
};

// --- Обработка очереди для обновления токена ---
let isRefreshing = false;
let failedQueue = [];

const processQueue = (error, token = null) => {
    failedQueue.forEach(prom => {
        if (error) {
            prom.reject(error);
        } else {
            prom.resolve(token);
        }
    });
    failedQueue = [];
};

// --- Fetch с автоматическим обновлением токена ---
export const authFetch = async (url, options = {}) => {
    let response = await fetch(url, {
        ...options,
        headers: {
            'Authorization': `Bearer ${getAccessToken()}`,
            'Content-Type': 'application/json',
            ...options.headers,
        },
    });

    if (response.status === 401) {
        if (isRefreshing) {
            return new Promise((resolve, reject) => {
                failedQueue.push({ resolve, reject });
            }).then(token => {
                return fetch(url, {
                    ...options,
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json',
                        ...options.headers,
                    },
                });
            });
        }

        isRefreshing = true;
        try {
            const userData = await refreshTokens();
            isRefreshing = false;
            processQueue(null, getAccessToken());

            response = await fetch(url, {
                ...options,
                headers: {
                    'Authorization': `Bearer ${getAccessToken()}`,
                    'Content-Type': 'application/json',
                    ...options.headers,
                },
            });
        } catch (refreshError) {
            isRefreshing = false;
            processQueue(refreshError, null);
            logout();
            window.location.href = '/login';
            return Promise.reject(refreshError);
        }
    }

    return response;
};

// --- Login ---
export const login = async (email, password) => {
    const res = await fetch(`${API_URL}/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
    });

    if (!res.ok) {
        const text = await res.text();
        throw new Error(text || "Login failed");
    }

    const data = await res.json();
    saveTokens(data.accessToken, data.refreshToken);
    return getCurrentUser();
};

// --- Register ---
export const register = async (email, password) => {
    const res = await fetch(`${API_URL}/register`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
    });

    if (!res.ok) {
        const error = new Error("Ошибка регистрации");
        error.status = res.status;
        throw error;
    }

    return res.json().catch(() => ({}));
};

// --- Refresh токенов ---
export const refreshTokens = async () => {
    const refreshToken = getRefreshToken();
    if (!refreshToken) return null;

    const res = await fetch(`${API_URL}/refresh`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: refreshToken }),
    });

    if (!res.ok) {
        logout();
        return null;
    }

    const data = await res.json();
    saveTokens(data.accessToken, data.refreshToken);
    return getCurrentUser();
};

// --- Назначение роли (для админа) ---
export const assignRole = async (email, role) => {
    const res = await authFetch(`${API_URL}/assign-role`, {
        method: "POST",
        body: JSON.stringify({ email, role }),
    });

    if (!res.ok) {
        throw new Error("Ошибка назначения роли");
    }

    return res.json();
};

// --- Получение всех пользователей ---
export const getUsers = async () => {
    const res = await authFetch(`${API_URL}/users`, { method: "GET" });
    if (!res.ok) throw new Error("Ошибка получения пользователей");
    return res.json();
};
// ... существующий код ...

// --- Получение профиля пользователя по ID ---
export const getUserProfileById = async (userId) => {
    const res = await authFetch(`http://localhost:12717/api/users/${userId}`, {
        method: "GET"
    });

    if (!res.ok) {
        if (res.status === 403) {
            throw new Error("Доступ запрещен");
        } else if (res.status === 404) {
            throw new Error("Пользователь не найден");
        }
        throw new Error("Ошибка получения профиля");
    }

    return res.json();
};

// ... остальной код ...

// --- Получение всех пользователей (если нужно для списка) ---
export const getAllUsers = async () => {
    const res = await authFetch(`${API_URL}/users`, { method: "GET" });
    if (!res.ok) throw new Error("Ошибка получения пользователей");
    return res.json();
};
